// Concatenate the docs an LLM needs into docs/llms-full.txt (linked from llms.txt).
// Run after editing docs: node scripts/build-llms-full.mjs
import { readFileSync, writeFileSync } from "node:fs";

const SOURCES = [
  "README.md",
  "docs/guarantees.md",
  "docs/mcp.md",
  "docs/recipes/wrap-your-loop.md",
  "docs/recipes/human-approval.md",
  "docs/recipes/record-replay-testing.md",
  "docs/recipes/budgets.md",
];

const banner =
  "# Throughline - full documentation\n\n" +
  "Generated by scripts/build-llms-full.mjs from the files listed in llms.txt.\n";

const body = SOURCES.map((p) => `\n\n---\nsource: ${p}\n---\n\n${readFileSync(p, "utf8")}`).join(
  "",
);

writeFileSync("docs/llms-full.txt", banner + body);
console.log(`wrote docs/llms-full.txt from ${SOURCES.length} sources`);
